import { test, expect } from '@playwright/test';

// TC-LOGIN-001 — valid sign-in lands on the dashboard
test('TC-LOGIN-001 valid sign-in', { tag: '@smoke' }, async ({ page }) => {
  // Arrange
  await page.goto('/login');
  // Act
  await page.getByLabel('Email').fill('qa@example.com');
  await page.getByLabel('Password').fill('Passw0rd!');
  await page.getByRole('button', { name: 'Sign in' }).click();
  // Assert
  await expect(page).toHaveURL(/\/dashboard$/);
  await expect(page.getByText('Welcome, QA Tester')).toBeVisible();
});

// TC-LOGIN-002 — empty email is rejected
test('TC-LOGIN-002 empty email', async ({ page }) => {
  await page.goto('/login');
  await page.getByRole('button', { name: 'Sign in' }).click();
  await expect(page.getByRole('alert')).toHaveText('Email is required');
});
